import Play from "./Play";
import DiscImageDevice from "./DiscImageDevice";

export let PlayModule : any = null;

// Emscripten sets HOME=/home/user; saves land in /home/user/.local/share/Play Data Files/
const IDBFS_MOUNT = "/home/web_user";

let initPromise : Promise<void> | null = null;

let module_overrides = {
    locateFile: function(path : string) {
        const baseURL = window.location.origin + window.location.pathname.substring(0, window.location.pathname.lastIndexOf("/"));
        return baseURL + '/' + path;
    },
    mainScriptUrlOrBlob: "",
};

export let initPlayModule = async function() {
    // Guard against React StrictMode double-invocation
    if(initPromise) return initPromise;
    initPromise = (async () => {
        module_overrides.mainScriptUrlOrBlob = module_overrides.locateFile('Play.js');
        PlayModule = await Play(module_overrides);
        PlayModule.FS.mkdir("/work");

        // Mount IndexedDB-backed filesystem so saves persist across sessions
        try {
            try { PlayModule.FS.mkdir(IDBFS_MOUNT); } catch(e) { /* already exists */ }
            PlayModule.FS.mount(PlayModule.FS.filesystems.IDBFS, {}, IDBFS_MOUNT);

            // Load existing saves from IndexedDB (5 second timeout so we never hang)
            await Promise.race([
                new Promise<void>((resolve) => {
                    PlayModule.FS.syncfs(true, (err: any) => {
                        if(err) console.warn("Failed to load saves from IndexedDB:", err);
                        resolve();
                    });
                }),
                new Promise<void>((resolve) => setTimeout(resolve, 5000)),
            ]);

            // Flush saves to IndexedDB every 30 seconds
            setInterval(() => {
                PlayModule.FS.syncfs(false, (err: any) => {
                    if(err) console.warn("Failed to sync saves to IndexedDB:", err);
                });
            }, 30000);
        } catch(e) {
            console.warn("IDBFS setup failed, saves will not persist:", e);
        }

        PlayModule.discImageDevice = new DiscImageDevice(PlayModule);
        PlayModule.ccall("initVm", "", [], []);
    })();
    return initPromise;
};
